SELECT p.gender, p.age, s.hadm_id, s.icu_stay_id, s.intime, s.outtime, s.los, s.deathtime, d.icd_code, d.icd_version, l.itemid, l.value, l.valuenum, l.valueuom, m.map, m.hr, i.iqr, rank() OVER (PARTITION BY p.gender, p.age, s.hadm_id ORDER BY l.value ASC) AS percentile_rank, avg(m.map) OVER (PARTITION BY p.gender, p.age, s.hadm_id ORDER BY l.value ASC ROWS BETWEEN UNBOUNDED preceding AND CURRENT ROW) AS avg_map_before, lag(m.map) OVER (PARTITION BY p.gender, p.age, s.hadm_id ORDER BY l.value ASC) AS previous_map, lead(m.map) OVER (PARTITION BY p.gender, p.age, s.hadm_id ORDER BY l.value ASC) AS next_map FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays s ON a.hadm_id = s.subject_id JOIN labevents l ON s.icu_stay_id = l.stay_id AND l.charttime BETWEEN s.intime AND s.outtime JOIN diagnoses_icd d ON l.itemid = d.icd_code AND l.value = d.icd_version JOIN (SELECT subject_id, MAP, HR, iqr FROM microbiologyevents WHERE charttime BETWEEN intime AND outtime AND (MAP < 65 OR HR > 100)) m ON m.subject_id = s.subject_id JOIN (SELECT icu_stay_id, iqr FROM icustays WHERE intime BETWEEN 0 AND 72) i ON i.icu_stay_id = s.icu_stay_id;